    for icon, lesson in zip(["📥", "🪪", "🔑", "📸"], LESSONS):
        if st.button(icon + " " + {"앱 설치하기":"앱 받기", "회원가입하기":"처음 가입", "로그인하기":"들어가기", "화면 사진 남기기":"화면 찍기"}[lesson]):
            st.session_state.lesson = lesson
